        "<style id=\"pz-styles\">",
        "  .project-img.pz-ready { cursor: zoom-in; }",
        "  .project-img.pz-ready:focus-visible {",
        "    outline: 3px solid var(--clr-accent2);",
        "    outline-offset: -4px;               /* à l'intérieur : la carte a overflow:hidden */",
        "  }",
        "  .pz-hint {",
        "    position: absolute; left: .7rem; bottom: .7rem; z-index: 4;",
        "    display: inline-flex; align-items: center; gap: .4rem;",
        "    font-family: var(--font-mono); font-size: .74rem; font-weight: 600;",
        "    letter-spacing: .05em; text-transform: uppercase;",
        "    color: #f8fafc; background: rgba(6,13,26,.86);",
        "    border: 1px solid rgba(147,197,253,.45);",
        "    padding: .3rem .65rem; border-radius: 100px;",
        "    opacity: 0; transform: translateY(6px);",
        "    transition: opacity .25s ease, transform .25s ease;",
        "    pointer-events: none;",
        "  }",
        "  .project-img .pz-hint i { font-size: .8rem; opacity: 1; color: #93c5fd; z-index: auto; }",
        "  .project-img.pz-ready:hover .pz-hint,",
        "  .project-img.pz-ready:focus-visible .pz-hint { opacity: 1; transform: none; }",
        "",
        "  .pz-modal {",
        "    position: fixed; inset: 0; z-index: 10000;",
        "    display: flex; align-items: center; justify-content: center;",
        "    padding: clamp(.75rem, 3vw, 2.5rem);",
        "    background: rgba(3,7,15,.88);",
        "    backdrop-filter: blur(10px) saturate(120%);",
        "    -webkit-backdrop-filter: blur(10px) saturate(120%);",
        "    opacity: 0; visibility: hidden;",
        "    transition: opacity .3s ease, visibility 0s linear .3s;",
        "  }",
        "  .pz-modal.pz-open { opacity: 1; visibility: visible; transition: opacity .3s ease; }",
        "  [data-theme=\"light\"] .pz-modal { background: rgba(226,232,240,.9); }",
        "",
        "  .pz-dialog {",
        "    position: relative; width: min(1180px, 100%);",
        "    max-height: 100%;",
        "    display: flex; flex-direction: column;",
        "    background: #0b1628;",
        "    border: 1px solid rgba(96,165,250,.28);",
        "    border-radius: 18px;",
        "    box-shadow: 0 30px 80px rgba(0,0,0,.6), 0 0 0 1px rgba(255,255,255,.04) inset, 0 0 60px rgba(59,130,246,.18);",
        "    overflow: hidden;",
        "    transform: translateY(14px) scale(.97);",
        "    transition: transform .35s cubic-bezier(.2,.8,.2,1);",
        "  }",
        "  .pz-modal.pz-open .pz-dialog { transform: none; }",
        "  [data-theme=\"light\"] .pz-dialog {",
        "    background: #ffffff;",
        "    border-color: rgba(37,99,235,.25);",
        "    box-shadow: 0 30px 70px rgba(15,23,42,.25), 0 0 0 1px rgba(15,23,42,.04) inset;",
        "  }",
        "  .pz-dialog::before {",
        "    content: ''; position: absolute; left: 0; right: 0; top: 0; height: 3px; z-index: 3;",
        "    background: linear-gradient(90deg, #3b82f6, #22d3ee, #3b82f6);",
        "  }",
        "",
        "  .pz-stage {",
        "    position: relative; flex: 1; min-height: 0;",
        "    display: flex; align-items: center; justify-content: center;",
        "    background: #050a14;",
        "    overflow: hidden;",
        "  }",
        "  [data-theme=\"light\"] .pz-stage { background: #e2e8f0; }",
        "  .pz-img {",
        "    display: block; width: 100%; height: auto;",
        "    max-height: calc(100vh - 11rem);",
        "    object-fit: contain;",
        "    user-select: none; -webkit-user-drag: none;",
        "    transition: opacity .25s ease;",
        "  }",
        "  .pz-img.pz-fade { opacity: 0; }",
        "  .pz-stage.pz-zoomed { overflow: auto; align-items: flex-start; justify-content: flex-start; cursor: zoom-out; }",
        "  .pz-stage.pz-zoomed .pz-img { width: 1800px; max-width: none; max-height: none; }",
        "  .pz-stage:not(.pz-zoomed) { cursor: zoom-in; }",
        "",
        "  .pz-btn {",
        "    width: 48px; height: 48px; border-radius: 50%;",
        "    display: inline-flex; align-items: center; justify-content: center;",
        "    font-size: 1.05rem; cursor: pointer;",
        "    color: #f1f5f9; background: rgba(11,22,40,.88);",
        "    border: 1px solid rgba(147,197,253,.4);",
        "    box-shadow: 0 6px 18px rgba(0,0,0,.4);",
        "    transition: background .2s ease, transform .2s ease, border-color .2s ease;",
        "  }",
        "  .pz-btn:hover { background: #1d4ed8; border-color: #93c5fd; transform: scale(1.06); }",
        "  .pz-btn:focus-visible { outline: 3px solid #fbbf24; outline-offset: 3px; }",
        "  [data-theme=\"light\"] .pz-btn { color: #0f172a; background: rgba(255,255,255,.95); border-color: rgba(37,99,235,.35); box-shadow: 0 6px 18px rgba(15,23,42,.18); }",
        "  [data-theme=\"light\"] .pz-btn:hover { color: #ffffff; background: #1d4ed8; border-color: #1d4ed8; }",
        "  [data-theme=\"light\"] .pz-btn:focus-visible { outline-color: #1d4ed8; }",
        "  .pz-prev, .pz-next { position: absolute; top: 50%; transform: translateY(-50%); z-index: 2; }",
        "  .pz-prev { left: .9rem; } .pz-next { right: .9rem; }",
        "  .pz-prev:hover, .pz-next:hover { transform: translateY(-50%) scale(1.06); }",
        "  .pz-stage.pz-zoomed ~ .pz-prev, .pz-stage.pz-zoomed ~ .pz-next { display: none; }",
        "",
        "  .pz-caption {",
        "    display: flex; align-items: center; gap: 1rem; flex-wrap: wrap;",
        "    padding: .9rem 1.2rem;",
        "    border-top: 1px solid rgba(96,165,250,.2);",
        "    background: #0b1628;",
        "  }",
        "  [data-theme=\"light\"] .pz-caption { background: #ffffff; border-top-color: rgba(37,99,235,.18); }",
        "  .pz-text { flex: 1; min-width: 220px; }",
        "  .pz-cat {",
        "    display: block; font-family: var(--font-mono); font-size: .78rem;",
        "    letter-spacing: .08em; text-transform: uppercase; color: #67e8f9;",
        "  }",
        "  [data-theme=\"light\"] .pz-cat { color: #155e75; }",
        "  .pz-title {",
        "    margin: .15rem 0 0; font-family: var(--font-display); font-weight: 700;",
        "    font-size: clamp(1rem, 2vw, 1.25rem); line-height: 1.3; color: #f8fafc;",
        "  }",
        "  [data-theme=\"light\"] .pz-title { color: #0f172a; }",
        "  .pz-keys { font-size: .85rem; color: #cbd5e1; }",
        "  [data-theme=\"light\"] .pz-keys { color: #334155; }",
        "  .pz-keys kbd {",
        "    font-family: var(--font-mono); font-size: .75rem;",
        "    padding: .05rem .4rem; border-radius: 4px;",
        "    border: 1px solid currentColor; background: transparent; color: inherit;",
        "    box-shadow: none;",
        "  }",
        "  .pz-count {",
        "    font-family: var(--font-mono); font-weight: 600; font-size: .9rem;",
        "    color: #f8fafc; background: rgba(59,130,246,.22);",
        "    border: 1px solid rgba(147,197,253,.4);",
        "    padding: .25rem .7rem; border-radius: 100px;",
        "  }",
        "  [data-theme=\"light\"] .pz-count { color: #1e3a8a; background: #dbeafe; border-color: #93c5fd; }",
        "  .pz-tools { display: flex; gap: .5rem; }",
        "",
        "  html.pz-lock { overflow: hidden; }",
        "",
        "  @media (max-width: 640px) {",
        "    .pz-keys { display: none; }",
        "    .pz-btn { width: 44px; height: 44px; }",
        "    .pz-prev { left: .4rem; } .pz-next { right: .4rem; }",
        "  }",
        "  @media (prefers-reduced-motion: reduce) {",
        "    .pz-modal, .pz-dialog, .pz-img, .pz-btn, .pz-hint { transition: none !important; }",
        "  }",
        "  @media print { .pz-modal, .pz-hint { display: none !important; } }",
        "</style>",
