        "  <button id=\"backToTop\" aria-label=\"Retourner en haut de la page\" title=\"Retour en haut\">",
        "    <svg viewBox=\"0 0 54 54\" aria-hidden=\"true\" focusable=\"false\">",
        "      <circle class=\"progress-ring\" cx=\"27\" cy=\"27\" r=\"24\"></circle>",
