        "    }",
        "",
        "    if (d.badge_statut) {",
        "      document.querySelectorAll('.dispo-badge').forEach(function (db) {",
        "        var dd = db.querySelector('.dispo-dot');",
        "        db.innerHTML = ''; if (dd) db.appendChild(dd);",
        "        db.appendChild(document.createTextNode(' ' + d.badge_statut));",
        "      });",
        "    }",
        "",
        "    if (d.footer_location) {",
        "      document.querySelectorAll('.footer-location').forEach(function (fl) {",
        "        var links = fl.querySelectorAll('a');",
        "        fl.textContent = d.footer_location + ' ';",
        "        links.forEach(function (lnk) { fl.appendChild(lnk); });",
        "      });",
        "    }",
        "",
        "    if (d.nom) {",
        "      document.title = d.nom + ' – Portfolio | MODE 83';",
        "      var md = document.querySelector('meta[name=\"description\"]');",
        "      if (md && d.titre) md.setAttribute('content', 'Portfolio de ' + d.nom + ' – ' + d.titre + '.');",
        "    }",
        "  }",
        "",
        "  function buildSummary(d) {",
        "    var rows = [];",
        "    if (d.nom)          rows.push('<strong>Nom</strong> : '           + d.nom);",
        "    if (d.titre)        rows.push('<strong>Titre</strong> : '         + d.titre);",
        "    if (d.email)        rows.push('<strong>Email</strong> : '         + d.email);",
        "    if (d.telephone)    rows.push('<strong>Tél</strong> : '           + d.telephone);",
        "    if (d.localisation) rows.push('<strong>Lieu</strong> : '          + d.localisation);",
        "    if (d.competences && d.competences.length)",
        "      rows.push('<strong>Compétences</strong> : ' + d.competences.length + ' extraites');",
        "    if (d.experiences && d.experiences.length)",
        "      rows.push('<strong>Expériences</strong> : ' + d.experiences.length + ' extraites');",
        "    if (d.certifications && d.certifications.length)",
        "      rows.push('<strong>Formation/certs</strong> : ' + d.certifications.length + ' extraites');",
        "    if (d.soft_skills && d.soft_skills.length)",
        "      rows.push('<strong>Soft skills</strong> : ' + d.soft_skills.length + ' extraits');",
        "    return rows.length",
        "      ? rows.join('<br>')",
        "      : '<em>Peu de données structurées détectées — utilisez « Éditer » pour compléter.</em>';",
        "  }",
        "",
        "  function handleFile(file) {",
        "    if (!file || file.type !== 'application/pdf') {",
