        "        setProgress(85, 'Application dans la page…');",
        "        applyToDom(data);",
        "        setProgress(100, '');",
        "",
        "        var summary = buildSummary(data);",
        "        showResult(",
        "          '✅ <strong>Portfolio mis à jour !</strong><br><br>' + summary +",
        "          '<br><br><em>Fermez cette fenêtre et utilisez « <strong>Éditer</strong> » pour affiner les détails.</em>',",
        "          false",
        "        );",
        "        showToast('✅ CV importé — portfolio mis à jour !');",
