        "  }",
        "",
        "})();",
        "</script>",
        "",
        "<script>",
        "(function () {",
        "  'use strict';",
        "",
        "  let _ctx = null;",
        "  function getCtx() {",
        "    if (!_ctx) _ctx = new (window.AudioContext || window.webkitAudioContext)();",
        "    if (_ctx.state === 'suspended') _ctx.resume();",
        "    return _ctx;",
        "  }",
        "",
        "  function playClickSound() {",
        "    const ac  = getCtx();",
        "    const now = ac.currentTime;",
        "",
        "    const osc1 = ac.createOscillator();",
        "    const g1   = ac.createGain();",
        "    osc1.type  = 'sawtooth';",
        "    osc1.frequency.setValueAtTime(90, now);",
        "    osc1.frequency.exponentialRampToValueAtTime(520, now + 0.14);",
        "    g1.gain.setValueAtTime(0,    now);",
        "    g1.gain.linearRampToValueAtTime(0.6,  now + 0.02);",
        "    g1.gain.exponentialRampToValueAtTime(0.001, now + 0.28);",
        "    osc1.connect(g1); g1.connect(ac.destination);",
        "    osc1.start(now); osc1.stop(now + 0.30);",
        "",
        "    const buf  = ac.createBuffer(1, Math.ceil(ac.sampleRate * 0.09), ac.sampleRate);",
        "    const data = buf.getChannelData(0);",
        "    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;",
        "    const src  = ac.createBufferSource();",
        "    const bpf  = ac.createBiquadFilter();",
        "    const g2   = ac.createGain();",
        "    src.buffer = buf;",
        "    bpf.type   = 'bandpass';",
        "    bpf.frequency.value = 1000;",
        "    bpf.Q.value = 0.8;",
        "    g2.gain.setValueAtTime(0.55, now);",
        "    g2.gain.exponentialRampToValueAtTime(0.001, now + 0.09);",
        "    src.connect(bpf); bpf.connect(g2); g2.connect(ac.destination);",
        "    src.start(now); src.stop(now + 0.10);",
        "  }",
        "",
        "  function playArrivalSound() {",
        "    const ac  = getCtx();",
        "    const now = ac.currentTime;",
        "",
        "    [[523.25, 0.60], [783.99, 0.50], [1046.50, 0.40]].forEach(function (pair) {",
        "      const freq = pair[0], vol = pair[1];",
        "      const osc  = ac.createOscillator();",
        "      const g    = ac.createGain();",
        "      osc.type   = 'sine';",
        "      osc.frequency.value = freq;",
        "      g.gain.setValueAtTime(0,   now);",
        "      g.gain.linearRampToValueAtTime(vol, now + 0.012);",
        "      g.gain.exponentialRampToValueAtTime(0.001, now + 1.4);",
        "      osc.connect(g); g.connect(ac.destination);",
        "      osc.start(now); osc.stop(now + 1.45);",
        "    });",
        "",
        "    const oscB  = ac.createOscillator();",
        "    const gB    = ac.createGain();",
        "    oscB.type   = 'triangle';",
        "    oscB.frequency.value = 2200;",
        "    gB.gain.setValueAtTime(0.35, now);",
        "    gB.gain.exponentialRampToValueAtTime(0.001, now + 0.7);",
        "    oscB.connect(gB); gB.connect(ac.destination);",
        "    oscB.start(now); oscB.stop(now + 0.75);",
        "",
        "    const oscS  = ac.createOscillator();",
        "    const gS    = ac.createGain();",
        "    oscS.type   = 'sine';",
        "    oscS.frequency.setValueAtTime(110, now);",
        "    oscS.frequency.exponentialRampToValueAtTime(55, now + 0.15);",
        "    gS.gain.setValueAtTime(0.7, now);",
        "    gS.gain.exponentialRampToValueAtTime(0.001, now + 0.18);",
        "    oscS.connect(gS); gS.connect(ac.destination);",
        "    oscS.start(now); oscS.stop(now + 0.20);",
        "  }",
        "",
        "  let _scrollingToTop = false;",
        "",
        "  document.addEventListener('DOMContentLoaded', function () {",
        "    const btn = document.getElementById('backToTop');",
        "    if (!btn) return;",
        "",
        "    btn.addEventListener('click', function () {",
        "      playClickSound();",
        "      _scrollingToTop = true;",
        "    });",
        "",
        "    window.addEventListener('scroll', function () {",
        "      if (_scrollingToTop && window.scrollY === 0) {",
        "        _scrollingToTop = false;",
        "        playArrivalSound();",
        "      }",
        "    }, { passive: true });",
        "  });",
        "",
        "})();",
        "</script>",
