        "      var b = e.target.closest('button');",
        "      if (e.target === modal) { close(); return; }",
        "      if (!b) return;",
        "      if (b.id === 'pdfx-close') close();",
        "      else if (b.id === 'pdfx-print') doPrint();",
        "      else if (b.hasAttribute('data-pdfx-theme')) { st.theme = b.getAttribute('data-pdfx-theme'); applyClasses(); }",
        "      else if (b.hasAttribute('data-pdfx-size')) { st.size = b.getAttribute('data-pdfx-size'); savePrefs(); applyClasses(); }",
        "      else if (b.hasAttribute('data-pdfx-zoom')) {",
        "        var z = b.getAttribute('data-pdfx-zoom'), cur = currentScale();",
        "        st.zoom = z === 'fit' ? 'fit' : Math.max(.4, Math.min(2.5, Math.round((cur + (z === '+' ? .1 : -.1)) * 10) / 10));",
        "        layout();",
        "      }",
        "    });",
        "    modal.addEventListener('keydown', function (e) {",
        "      if (e.key === 'Escape') { e.preventDefault(); close(); return; }",
        "      if (e.key !== 'Tab') return;",
        "      var f = $$('button:not([disabled]), [tabindex=\"0\"]', modal);",
        "      if (!f.length) return;",
        "      if (e.shiftKey && document.activeElement === f[0]) { e.preventDefault(); f[f.length - 1].focus(); }",
        "      else if (!e.shiftKey && document.activeElement === f[f.length - 1]) { e.preventDefault(); f[0].focus(); }",
        "    });",
        "    window.addEventListener('resize', function () { if (modal.classList.contains('pdfx-open')) layout(); });",
        "  }",
        "",
        "  function syncButtons() {",
        "    $$('[data-pdfx-theme]', modal).forEach(function (b) { b.setAttribute('aria-pressed', String(b.getAttribute('data-pdfx-theme') === st.theme)); });",
        "    $$('[data-pdfx-size]', modal).forEach(function (b) { b.setAttribute('aria-pressed', String(b.getAttribute('data-pdfx-size') === st.size)); });",
        "    $$('[data-pdfx-zoom=\"fit\"]', modal).forEach(function (b) { b.setAttribute('aria-pressed', String(st.zoom === 'fit')); });",
