        "      '@page{size:210mm ' + H + 'px;margin:0}' +",
        "      'html,body{height:' + H + 'px!important;min-height:' + H + 'px;overflow:hidden!important}';",
        "    st.H = H;",
        "    st.ready = true;",
        "    btnPrint.disabled = false;",
        "    loader.hidden = true;",
        "    layout();",
        "    info.innerHTML = '<strong>1 page continue</strong> · largeur A4 (210 mm) · hauteur ' + mm + ' mm · thème ' +",
        "                     (st.theme === 'dark' ? 'sombre' : 'clair');",
        "    announce('Aperçu prêt : une seule page continue au format A4, thème ' + (st.theme === 'dark' ? 'sombre' : 'clair') + '.');",
